"""Compare monograph frequency profiles from the K-037 historical panel."""

import argparse
from collections import Counter, defaultdict
from dataclasses import dataclass
from itertools import combinations
import json
import math
from pathlib import Path
import re
from statistics import fmean, median

from historical import historical_pages
from vs import corpus, ivtff


GROUPS = ("biological_b", "herbal_a", "herbal_b")
WIDTHS = (350, 375, 400)
ROOT = Path(__file__).resolve().parent


def physical_leaf(folio):
    return int(re.match(r"f([0-9]+)", folio).group(1))


@dataclass
class Observation:
    folio: str
    group: str
    glyphs: list[str]

    @property
    def block(self):
        return physical_leaf(self.folio)


def profiles(observations, alphabet):
    vectors = {}
    for obs in observations:
        counts = Counter(obs.glyphs)
        vectors[obs.folio] = tuple(counts[glyph] / len(obs.glyphs) for glyph in alphabet)
    return vectors


def distance(left, right):
    width = len(left)
    mean = 1.0 / width
    center_l = [frequency - mean for frequency in left]
    center_r = [frequency - mean for frequency in right]
    divisor = math.sqrt(math.fsum(x * x for x in center_l) * math.fsum(y * y for y in center_r))
    correlation = math.fsum(x * y for x, y in zip(center_l, center_r)) / divisor
    return 1.0 - correlation, math.fsum(abs(x - y) for x, y in zip(left, right))


def alphabet_of(observations):
    return sorted({glyph for obs in observations for glyph in obs.glyphs})


def group_summary(observations, alphabet):
    vectors = profiles(observations, alphabet)
    support = {
        group: {
            "sides": sum(obs.group == group for obs in observations),
            "physical_folios": len({obs.block for obs in observations if obs.group == group}),
        }
        for group in GROUPS
    }
    cells = defaultdict(lambda: defaultdict(list))
    for left, right in combinations(observations, 2):
        if left.block == right.block:
            continue
        cell = "/".join(sorted((left.group, right.group)))
        pair = tuple(sorted((left.block, right.block)))
        cells[cell][pair].append(distance(vectors[left.folio], vectors[right.folio]))

    table = {}
    for cell, physical_pairs in sorted(cells.items()):
        table[cell] = {
            "physical_folio_pairs": len(physical_pairs),
            "side_pairs": sum(map(len, physical_pairs.values())),
            "median_correlation_distance": rounded(
                median(fmean(values[0] for values in pair) for pair in physical_pairs.values())
            ),
            "median_manhattan_distance": rounded(
                median(fmean(values[1] for values in pair) for pair in physical_pairs.values())
            ),
        }

    named_case = next((obs for obs in observations if obs.folio == "f31r"), None)
    nearest = None
    if named_case:
        by_group = defaultdict(lambda: defaultdict(list))
        for obs in observations:
            if obs.block != named_case.block:
                by_group[obs.group][obs.block].append(distance(vectors[named_case.folio], vectors[obs.folio]))
        measures = {}
        for group, by_leaf in sorted(by_group.items()):
            measures[group] = {
                "physical_folios": len(by_leaf),
                "correlation_distance": rounded(
                    fmean(fmean(values[0] for values in pair) for pair in by_leaf.values())
                ),
                "manhattan_distance": rounded(
                    fmean(fmean(values[1] for values in pair) for pair in by_leaf.values())
                ),
            }
        nearest = {
            "distance_means_by_group": measures,
            "nearest_correlation_group": closest(measures, "correlation_distance"),
            "nearest_manhattan_group": closest(measures, "manhattan_distance"),
        }
    return {"alphabet_size": len(alphabet), "support": support, "pair_summary": table, "f31r": nearest}


def rounded(value):
    return round(value, 6)


def closest(rows, metric):
    return min(rows, key=lambda group: rows[group][metric]) if rows else None


def paragraph_index(page):
    return {line.id: line for line in page.lines if line.unit == "P"}


def line_glyphs(line, segmentation):
    return [
        glyph for word in line.words for glyph in ivtff.segment(word, segmentation)
        if glyph.isascii() and glyph.isalnum()
    ]


def common_paragraphs(left, right, segmentation):
    sides = [paragraph_index(page) for page in (left, right)]
    if not all(sides):
        return None, "no_paragraph_loci_in_one_transliteration"
    orders = [list(side) for side in sides]
    if orders[0][0] != orders[1][0]:
        return None, "first_paragraph_locus_differs"
    shared = [[key for key in order if key in sides[1 - i]] for i, order in enumerate(orders)]
    if shared[0] != shared[1]:
        return None, "shared_locus_order_differs"
    usable = shared[0]
    left_glyphs = [line_glyphs(sides[0][key], segmentation) for key in usable]
    right_glyphs = [line_glyphs(sides[1][key], segmentation) for key in usable]
    return (usable, left_glyphs, right_glyphs, [len(order) - len(usable) for order in orders]), None


def windows(shared, width, later):
    loci, left, right, omitted = shared
    start = 0
    if later:
        left_size = right_size = 0
        for start, (left_line, right_line) in enumerate(zip(left, right), start=1):
            left_size += len(left_line)
            right_size += len(right_line)
            if min(left_size, right_size) >= width:
                break
        if start == len(loci):
            return None
    selected = [[glyph for line in side[start:] for glyph in line] for side in (left, right)]
    if any(len(glyphs) < width for glyphs in selected):
        return None
    return loci[start], [glyphs[:width] for glyphs in selected], omitted


def historical_profile(panel, source, alphabet, width, later, allow_truncation=False):
    offset = width if later else 0
    included, exclusions = [], {}
    for row in panel:
        sequence = source.get(row["old_page"], [])
        if len(sequence) < offset + width and not allow_truncation:
            exclusions[row["folio"]] = "historical glyphs available: " + str(len(sequence))
            continue
        included.append(Observation(row["folio"], row["group"], sequence[offset:offset + width]))
    return {"observed_sides": len(included), "exclusions": exclusions, **group_summary(included, alphabet)}


def historical_omit_one_leaf(panel, source, alphabet):
    omitted_leaves = {physical_leaf(row["folio"]) for row in panel} - {physical_leaf("f31r")}
    outcomes = Counter()
    margins = [[], []]
    for omitted in sorted(omitted_leaves):
        reduced_panel = [row for row in panel if physical_leaf(row["folio"]) != omitted]
        summary = historical_profile(reduced_panel, source, alphabet, 400, False, allow_truncation=True)
        result = summary["f31r"]
        outcomes[result["nearest_correlation_group"], result["nearest_manhattan_group"]] += 1
        by_group = result["distance_means_by_group"]
        for index, metric in enumerate(("correlation_distance", "manhattan_distance")):
            margins[index].append(by_group["herbal_b"][metric] - by_group["biological_b"][metric])
    return {
        "omissions": len(omitted_leaves),
        "outcomes_by_correlation_then_manhattan": {"/".join(groups): count for groups, count in outcomes.items()},
        "herbal_b_minus_biological_b_distance_margin_ranges": {
            metric: [rounded(min(margins[index])), rounded(max(margins[index]))]
            for index, metric in enumerate(("correlation", "manhattan"))
        },
    }


def modern_profile(panel, public_left, public_right, width, later, segmentation):
    sets = [[], []]
    start_loci = {}
    exclusions = {}
    omitted = {}
    for row in panel:
        folio = row["folio"]
        if folio not in public_left or folio not in public_right:
            exclusions[folio] = "unavailable_as_joint_public_practice_pair"
            continue
        shared, error = common_paragraphs(public_left[folio], public_right[folio], segmentation)
        if error:
            exclusions[folio] = error
            continue
        paired = windows(shared, width, later)
        if paired is None:
            exclusions[folio] = "no_joint_complete_window"
            continue
        start_loci[folio], glyph_lists, omitted[folio] = paired
        for index, glyphs in enumerate(glyph_lists):
            sets[index].append(Observation(folio, row["group"], glyphs))
    alphabet = alphabet_of(sets[0] + sets[1])
    return {
        "observed_sides": len(sets[0]),
        "start_loci": start_loci,
        "unmatched_paragraph_loci_by_version": omitted,
        "exclusions": exclusions,
        "zl": group_summary(sets[0], alphabet),
        "it": group_summary(sets[1], alphabet),
    }


def within_hand(public_left, public_right, width):
    joint = defaultdict(list)
    for folio, page in public_left.items():
        if page.language != "B" or page.section not in ("H", "B") or not page.hand:
            continue
        if folio not in public_right:
            continue
        shared, error = common_paragraphs(page, public_right[folio], "eva-basic")
        if error:
            continue
        paired = windows(shared, width, later=False)
        if paired is None:
            continue
        joint[page.hand].append((folio, "herbal_b" if page.section == "H" else "biological_b", paired[1]))

    observed = {}
    for hand, rows in sorted(joint.items()):
        observations = [
            [Observation(folio, group, values[i]) for folio, group, values in rows]
            for i in (0, 1)
        ]
        alphabet = alphabet_of(observations[0] + observations[1])
        versions = [group_summary(version, alphabet) for version in observations]
        support = versions[0]["support"]
        observed[hand] = {"support": support}
        if all(support[group]["physical_folios"] >= 2 for group in ("biological_b", "herbal_b")):
            observed[hand]["zl"], observed[hand]["it"] = versions
    return observed


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("historical", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    panel = json.loads((ROOT / "panel.json").read_text())
    historical = historical_pages(args.historical)
    historical_alphabet = sorted({glyph for row in panel for glyph in historical[row["old_page"]]})
    modern_left, modern_right = (
        {page.id: page for page in corpus.split_pages("practice", transliteration)[1]}
        for transliteration in ("zl", "it")
    )
    result = {
        "panel_rows": len(panel),
        "historical": {},
        "modern_basic": {},
        "modern_raw": {},
        "within_hand": {str(width): within_hand(modern_left, modern_right, width) for width in WIDTHS},
    }
    for width in WIDTHS:
        for later in (False, True):
            key = ("later" if later else "first") + "_" + str(width)
            result["historical"][key] = historical_profile(panel, historical, historical_alphabet, width, later)
            result["modern_basic"][key] = modern_profile(
                panel, modern_left, modern_right, width, later, "eva-basic"
            )
    result["modern_raw"]["first_375"] = modern_profile(
        panel, modern_left, modern_right, 375, False, "eva-raw"
    )
    result["historical"]["first_capped_at_400"] = historical_profile(
        panel, historical, historical_alphabet, 400, False, allow_truncation=True
    )
    short_panel = [row for row in panel if len(historical[row["old_page"]]) >= 400]
    result["historical"]["matched_first_200"] = historical_profile(
        short_panel, historical, historical_alphabet, 200, False
    )
    result["historical"]["matched_second_200"] = historical_profile(
        short_panel, historical, historical_alphabet, 200, True
    )
    result["historical_omit_one_leaf"] = historical_omit_one_leaf(panel, historical, historical_alphabet)
    args.output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n")


if __name__ == "__main__":
    main()
